var car=UnityEngine.Object.FindAnyObjectByType<Racer.ArcadeVehicle>();var race=UnityEngine.Object.FindAnyObjectByType<Racer.RaceDirector>();race.RestartRace();var props=UnityEngine.Object.FindObjectsByType<Racer.BreakableProp>();var yieldMethod=typeof(Racer.BreakableProp).GetMethod("Yield",System.Reflection.BindingFlags.NonPublic|System.Reflection.BindingFlags.Instance);
